//! Generated protobuf types for the Elysium contract.
//!
//! The modules mirror the proto package hierarchy (`elysium.common.v1` becomes
//! [`common::v1`], `elysium.user.v1` becomes [`user::v1`]). The Rust files are
//! generated by [`build.rs`] into `OUT_DIR` and pulled in here via `include!`.
//! Do not edit the generated output; change the `.proto` files instead.

// Generated messages are the full contract; many are not yet referenced by
// handlers. `allow(dead_code)` keeps the complete vocabulary available without
// tripping `-D warnings`, per the Rust guideline that generated code may `allow`.

/// Shared vocabulary: timestamps, coordinates, money, pagination, and friends.
pub mod common {
    /// Version 1 of the common contract.
    #[allow(dead_code)]
    pub mod v1 {
        include!(concat!(env!("OUT_DIR"), "/elysium.common.v1.rs"));
    }
}

